#!/bin/bash
# Codex SessionStart hook — generated by scripts/gen-harness-codex.ts, do not edit.
# Hands core rules (scripts/core.txt) + `tea-rags prime "$PWD"` to the main session as
# hookSpecificOutput.additionalContext. A missing CLI or digest leaves core alone. Nothing here fails the hook.

cat > /dev/null
ROOT="${PLUGIN_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
CONTEXT=$(cat "$ROOT/scripts/core.txt" 2>/dev/null)
if command -v tea-rags > /dev/null 2>&1 && command -v python3 > /dev/null 2>&1; then
  DIGEST=$(tea-rags prime "$PWD" 2>/dev/null | python3 -I "$ROOT/scripts/fit-digest.py" 8700 "${#CONTEXT}" 2>/dev/null)
  if [ -n "$DIGEST" ]; then
    CONTEXT="$CONTEXT

$DIGEST"
  fi
fi
if [ -z "$CONTEXT" ]; then
  exit 0
fi

jq -n --arg context "$CONTEXT" '{
  hookSpecificOutput: {
    hookEventName: "SessionStart",
    additionalContext: $context
  }
}'
exit 0
